<?php $pageTitle='My Classes'; require_once __DIR__.'/../includes/header.php';$st=$pdo->prepare("SELECT c.* FROM teacher_classes tc JOIN teachers t ON t.id=tc.teacher_id JOIN classes c ON c.id=tc.class_id WHERE t.user_id=?");$st->execute([user()['id']]);$rows=$st->fetchAll(); ?><h2>My Classes</h2><div class="row g-3"><?php foreach($rows as $r): ?><div class="col-md-4"><div class="card p-4"><h5><?=e($r['name'].' '.$r['section'])?></h5><div><?=e($r['level'])?></div></div></div><?php endforeach;?></div><?php require __DIR__.'/../includes/footer.php';